import 'package:flutter/material.dart';
class BmiCalculatorScreen extends StatefulWidget{const BmiCalculatorScreen({super.key});@override State<BmiCalculatorScreen> createState()=>_B();}class _B extends State<BmiCalculatorScreen>{final h=TextEditingController();final w=TextEditingController();double? bmi;String get cat=>bmi==null?'':bmi!<18.5?'Underweight':bmi!<25?'Healthy':bmi!<30?'Overweight':'Obese';@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('BMI Calculator')),body:ListView(padding:const EdgeInsets.all(24),children:[TextField(controller:h,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Height (cm)')),const SizedBox(height:12),TextField(controller:w,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Weight (kg)')),const SizedBox(height:16),FilledButton(onPressed:(){final height=double.tryParse(h.text);final weight=double.tryParse(w.text);if(height==null||weight==null||height<=0||weight<=0){ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('Enter valid height and weight')));return;}setState(()=>bmi=weight/((height/100)*(height/100)));},child:const Text('Calculate')),if(bmi!=null)Card(child:Padding(padding:const EdgeInsets.all(20),child:Column(children:[Text(bmi!.toStringAsFixed(1),style:Theme.of(c).textTheme.displaySmall),Text(cat,style:Theme.of(c).textTheme.titleLarge),const Text('BMI is a screening tool. Ask a clinician for personal guidance.')])))]));}
